# apt.map — logical name -> real Debian/Ubuntu package(s).
# Only rows where the name actually differs from the logical name (§1); anything
# not listed passes through unchanged.

build = build-essential
dev-headers = libssl-dev pkg-config
fd = fd-find

# lcc (modules/lcc.c) is a 32-bit-only compiler; it needs gcc -m32 and the
# 32-bit libc to link the i386 binaries it emits.
multilib = gcc-multilib libc6-dev-i386

# amacc (modules/amacc.c) is an ARM32 JIT: the driver itself is a 32-bit ARM
# binary, so it is cross-built, and upstream's mk/arm.mk also demands qemu-arm
# on PATH before it will build at all. On an aarch64 host the driver can run
# without qemu (CONFIG_COMPAT), but only once libc6:armhf is there, which apt
# supplies only after `dpkg --add-architecture armhf`; the module falls back to
# qemu-arm when that step was not taken, so the row does not list it.
arm-cross = gcc-arm-linux-gnueabihf qemu-user

# Native-first (§1a G6): prefer the distro package so it updates via apt; fall
# back to a downloaded binary / install script only on releases that lack it.
# Availability was checked per release; a row exists ONLY where native is absent.
#
#             lsd      starship   fastfetch
#   bullseye  none     none       none        (Debian 11)
#   bookworm  native   none       none        (Debian 12)
#   trixie    native   native     native      (Debian 13)
#   jammy     none     none       none        (Ubuntu 22.04)
#   noble     native   none       none        (Ubuntu 24.04)
#   resolute  native   native     native      (Ubuntu 26.04)

# bullseye (Debian 11) has dpkg 1.20, which can't read modern zstd-compressed
# .debs -> use the release tarball binary (-> /usr/local/bin) there instead.
lsd@bullseye = source:provide_lsd_tarball
lsd@jammy    = source:provide_lsd_deb

fastfetch@bullseye = source:provide_fastfetch_tarball
fastfetch@bookworm = source:provide_fastfetch_deb
fastfetch@jammy    = source:provide_fastfetch_deb
fastfetch@noble    = source:provide_fastfetch_deb

starship@bullseye = script:https://starship.rs/install.sh --yes
starship@bookworm = script:https://starship.rs/install.sh --yes
starship@jammy    = script:https://starship.rs/install.sh --yes
starship@noble    = script:https://starship.rs/install.sh --yes

# chafa: yazi needs >= 1.16.0 (it passes --probe, added in that release) or the
# image preview renders nothing at all - see CHAFA_MIN in lib/build.sh. Same
# native-first table as above, and here EVERY apt release except resolute is too
# old, so the rows are the rule rather than the exception:
#
#   bullseye 1.6.0   bookworm 1.12.4   trixie   1.14.5
#   jammy    1.8.0   noble    1.14.0   resolute 1.18.1  <- the only native row
#
# Upstream publishes a source tarball only (no prebuilt binary for any distro),
# so provide_chafa compiles it - the one build here that isn't a download.
chafa@bullseye = source:provide_chafa
chafa@bookworm = source:provide_chafa
chafa@trixie   = source:provide_chafa
chafa@jammy    = source:provide_chafa
chafa@noble    = source:provide_chafa
# glib + freetype are chafa's mandatory deps; jpeg/webp/tiff are the optional
# loaders worth having (PNG and GIF decode is built into chafa itself).
chafa-build-deps = libglib2.0-dev libfreetype-dev libjpeg-dev libwebp-dev libtiff-dev pkg-config

# Überzug++ is what yazi actually drives on a graphical session (X11 always,
# Wayland under sway/Hyprland/niri/Wayfire), and no Debian/Ubuntu release
# packages it - so the source build is the ONLY route here. chafa headers come
# from provide_chafa's /usr/local install, which runs before this in the module.
ueberzugpp = source:provide_ueberzugpp
ueberzugpp-build-deps = libvips-dev libsixel-dev libssl-dev libtbb-dev libxcb1-dev libxcb-image0-dev libxcb-res0-dev libwayland-dev wayland-protocols extra-cmake-modules nlohmann-json3-dev libcli11-dev libfmt-dev libspdlog-dev librange-v3-dev pkg-config

# fzf: the zsh ↑ history picker passes --gutter, added in fzf 0.66.0, and an
# older fzf exits with `unknown option` instead of opening - see FZF_MIN in
# lib/build.sh. Packaged versions per release (repology):
#
#   bullseye 0.24.3   bookworm 0.38.0   trixie   0.60.3
#   jammy    0.29.0   noble    0.44.1   resolute 0.67.0  <- the only native row
#
# Upstream ships a static Go binary per arch, so this is a download, not a build.
fzf@bullseye = source:provide_fzf
fzf@bookworm = source:provide_fzf
fzf@trixie   = source:provide_fzf
fzf@jammy    = source:provide_fzf
fzf@noble    = source:provide_fzf

# Native name differences (Debian/Ubuntu).
go = golang
docker = docker.io
serie = cargo:serie          # not packaged on Debian/Ubuntu

# gh + btop are native on every release EXCEPT Debian 11 (bullseye) -> upstream
# release tarball there (bullseye's old dpkg can't take modern .debs anyway).
gh@bullseye   = source:provide_gh_tarball
btop@bullseye = source:provide_btop_tarball

# zig is native only on Ubuntu resolute; Debian + older Ubuntu build from
# the official ziglang.org tarball. ghostty likewise: native on resolute, else
# built from source (heavy). Build-dep name splits for the ghostty source path.
zig = source:provide_zig
zig@resolute = zig
# ghostty: native on resolute; community .deb on the releases the
# ghostty-ubuntu installer supports (Ubuntu 24.04 noble, Debian 13 trixie); Zig
# source build on the rest (jammy/bullseye/bookworm - no community binary).
ghostty = source:provide_ghostty
ghostty@resolute = ghostty
ghostty@noble = source:provide_ghostty_deb
ghostty@trixie = source:provide_ghostty_deb
xz = xz-utils
gtk4-dev = libgtk-4-dev
libadwaita-dev = libadwaita-1-dev

# Yandex Browser is in no Debian/Ubuntu archive; the vendor runs its own apt repo
# (modules/yandex-browser.sh), which the builder adds before installing.
yandex-browser = source:provide_yandex_browser


# zram-generator: Arch/Fedora/Void name it after the generator, Debian/Ubuntu
# prefix it with systemd- (modules/swap.sh).
zram-generator = systemd-zram-generator

# --- i3/X11 desktop (rices/i3-rosemary) ---------------------------------
# The i3 rice is validated on Void; these rows are name mapping only, so the same
# manifest resolves on Debian/Ubuntu too. Debian bundles most X client utilities
# into two packages, which is exactly the one-to-many case pkgmap exists for (§1).
xorg-xinit = xinit
xorg-xrandr = x11-xserver-utils
xorg-xset = x11-xserver-utils
xorg-xsetroot = x11-xserver-utils
xorg-xprop = x11-utils
xorg-xev = x11-utils
xorg-xkill = x11-utils
xorg-xdpyinfo = x11-utils
xorg-xinput = xinput
xorg-xauth = xauth
xorg-fonts-misc = xfonts-base
gnome-disks = gnome-disk-utility
gdk-pixbuf2 = libgdk-pixbuf-2.0-0
vulkan-icd-loader = libvulkan1
# Metapackages, not mesa-va-drivers/mesa-vdpau-drivers: those two names were
# dropped in Ubuntu 26.04 (resolute), while va-driver-all / vdpau-driver-all
# exist on every release here and pull mesa's backend in as a dependency.
libva-mesa-driver = va-driver-all
mesa-vdpau = vdpau-driver-all
noto-fonts = fonts-noto
noto-fonts-emoji = fonts-noto-color-emoji
noto-fonts-cjk = fonts-noto-cjk
ttf-liberation = fonts-liberation
ttf-dejavu = fonts-dejavu
gstreamer = libgstreamer1.0-0
gst-plugins-base = gstreamer1.0-plugins-base
gst-plugins-good = gstreamer1.0-plugins-good
gst-plugins-bad = gstreamer1.0-plugins-bad
gst-plugins-ugly = gstreamer1.0-plugins-ugly
gst-libav = gstreamer1.0-libav
gst-plugin-pipewire = gstreamer1.0-pipewire
gvfs-nfs = gvfs-backends
gvfs-smb = gvfs-backends
gvfs-mtp = gvfs-backends
gvfs-gphoto2 = gvfs-backends
gvfs-afc = gvfs-backends
gvfs-goa = gvfs-backends
polkit-gnome = policykit-1-gnome
network-manager-applet = network-manager-gnome
lm_sensors = lm-sensors
i3lock-color = i3lock
gtk-dark-theme = gnome-themes-extra
libva-utils = vainfo
# Debian splits the Kvantum style plugin per Qt major version; there is no
# `kvantum` package. Both, so Qt5 and Qt6 apps pick up the same style.
kvantum = qt5-style-kvantum qt6-style-kvantum
# Debian/Ubuntu package no Nerd Fonts symbols font, and there is no equivalent
# (fonts-symbola is Unicode emoji, not the Powerline/devicon private-use range).
# Empty RHS = skip: modules/theming.sh downloads a full Nerd Font anyway, which
# carries the same patched glyphs.
nerd-fonts-symbols =

# Soname-versioned Debian library packages (libpoppler-glib8, libjxl0.11, ...) are
# never mapped to a versioned name: it changes every release and the thumbnailers
# / pixbuf loaders pull the right one in as a dependency anyway. They still need a
# row, because an unmapped name passes through and fails the whole apt-get batch —
# see the empty-RHS block in the third pass below.

# --- i3 desktop, second pass (name mapping only) ------------------------------
xorg-xmodmap = x11-xserver-utils
p7zip = p7zip-full
unrar = unrar-free
sane = sane-utils
gutenprint = printer-driver-gutenprint
cups-pdf = printer-driver-cups-pdf
cpupower = linux-cpupower
lm_sensors = lm-sensors
gvfs-afc = gvfs-backends
# vscode has no Debian-archive package (Microsoft ships its own apt repo), so
# there is deliberately no row: pkg_install would fail loudly rather than
# install something that only looks like VS Code.

# --- evolution (modules/evolution.sh) -----------------------------------------
# The evolution/evolution-data-server/evolution-ews trio keeps its upstream names
# in Debian main (bullseye through trixie, jammy through resolute), so only the
# two support packages need rows.
#
# There is no binary package called `dconf` on Debian — the source package splits
# into dconf-cli (the tool) and dconf-gsettings-backend (the settings backend the
# module's `gsettings set` calls need in order to persist anything).
dconf = dconf-cli dconf-gsettings-backend
# Debian keeps the GLib command-line tools out of the runtime library package, so
# nothing pulls in `gsettings` implicitly the way glib2 does on Arch/Fedora.
glib2 = libglib2.0-bin

# --- thunderbird (modules/thunderbird.sh) -------------------------------------
# Native-first as everywhere else (§1a G6): a row exists ONLY on the releases
# that cannot give a usable Thunderbird, and the reason differs by release.
#
#             ships          why it can't stay native
#   bullseye  91 ESR         Exchange/EWS needs 140+
#   bookworm  115 ESR        same
#   trixie    128 ESR        same
#   jammy     115 ESR        same
#   noble     snap stub      `thunderbird` is a transitional package whose only
#   resolute  snap stub      job is `snap install thunderbird`; the snap moves the
#                            profile root to ~/snap/thunderbird/common/.thunderbird,
#                            where the module's user.js/userChrome.css layer is
#                            read by nothing.
#
# A release not listed here (a future Debian/Ubuntu that ships 140+ as a real deb)
# passes through to the archive package, and modules/thunderbird.sh's post-install
# version guard says so if that assumption turns out wrong.
#
# The route is Mozilla's official tarball, NOT packages.mozilla.org/apt: that repo
# publishes firefox only, so an apt-get install against it falls straight back to
# the archive's snap stub - the exact thing these rows exist to avoid.
thunderbird@bullseye = source:provide_thunderbird_tarball
thunderbird@bookworm = source:provide_thunderbird_tarball
thunderbird@trixie   = source:provide_thunderbird_tarball
thunderbird@jammy    = source:provide_thunderbird_tarball
thunderbird@noble    = source:provide_thunderbird_tarball
thunderbird@resolute = source:provide_thunderbird_tarball

# GPaste tracks GNOME Shell's version, and Debian/Ubuntu do not: resolute ships
# 45.3-5 against Shell 50, patched only to CLAIM compatibility in metadata.json.
# The mismatch costs the clipboard history, image support and a quiet panel all
# at once - see provide_gpaste. So source is the only route here, not a fallback.
gpaste = source:provide_gpaste
# meson/ninja/gettext build the project; gcr-4, gtk4 (+ its x11 backend),
# libadwaita and pango are the hard pkg-config deps in meson.build; the
# girepository pair builds the GIR the shell extension imports GPaste through;
# libx11/libxi back the X keybinder that X11 sessions fall back to.
gpaste-build-deps = meson ninja-build pkg-config gettext libgcr-4-dev libglib2.0-dev libgtk-4-dev libadwaita-1-dev libpango1.0-dev libgirepository-2.0-dev gobject-introspection libx11-dev libxi-dev

# turbostat/perf. Debian splits these: linux-cpupower carries turbostat,
# linux-perf the profiler. Neither is required by osr (see modules/benchmark.sh).
kernel-tools = linux-cpupower linux-perf

# --- i3 desktop, third pass: what actually blocked the rice on apt ------------
# Every row below was checked against the real binary index
#   deb.debian.org/debian/dists/{bullseye,bookworm,trixie}/*/binary-amd64
#   archive.ubuntu.com/ubuntu/dists/{jammy,noble}/*/binary-amd64
# not from memory, the same discipline xbps.map documents for Void. Without
# these the manifest does not merely lose a feature: _via_native batches the
# whole step into ONE apt-get, so a single unknown name fails the module.

# X session core (modules/xorg.sh, modules/input.sh). Debian names the server
# and the input driver after the source packages, and ships xkb data as xkb-data.
xorg-server = xserver-xorg
mesa-dri = libgl1-mesa-dri
xf86-input-libinput = xserver-xorg-input-libinput
xkeyboard-config = xkb-data
setxkbmap = x11-xkb-utils
# libnotify4 is the library and arrives as a dependency; notify-send - which
# every script in this rice calls - is in libnotify-bin, and only there.
libnotify = libnotify-bin
# polkit was renamed policykit-1 -> polkitd in bookworm; bullseye has only the
# old name (bookworm/jammy/noble carry both, so the new name covers them).
polkit = polkitd
polkit@bullseye = policykit-1

# Network, discovery, shares (modules/networkmanager.sh, avahi.sh, gvfs.sh).
networkmanager = network-manager
libnm = libnm0
openssh = openssh-client openssh-server
avahi = avahi-daemon avahi-utils
nss-mdns = libnss-mdns
nfs-utils = nfs-common

# Bluetooth + audio (modules/blueman.sh, modules/audio.sh). The codec libraries
# are what make a headset sound like more than SBC, and Debian soname-suffixes
# all three. sof-firmware lives in non-free-firmware as firmware-sof-signed -
# without it a modern Intel laptop has no sound at all and no log line saying so.
bluez-obex = bluez-obexd
sof-firmware = firmware-sof-signed
alsa-firmware = alsa-firmware-loaders
sbc = libsbc1
libfreeaptx = libfreeaptx0
libfreeaptx@bullseye =
libldac = libldacbt-enc2 libldacbt-abr2
# bullseye's PipeWire is 0.3.19 and predates WirePlumber (it used
# pipewire-media-session); there is nothing to install, so skip rather than fail.
wireplumber@bullseye =

# Secrets + thumbnailers (modules/keyring.sh, modules/thumbnails.sh).
# libsecret-tools carries secret-tool, which the CLI half of the stack uses.
libsecret = libsecret-1-0 libsecret-tools
# The pixbuf LOADER is the point of these two, not the codec library: without the
# loader, HEIC/SVG icons are blank everywhere including the browser download panel.
librsvg = librsvg2-common
libheif = heif-gdk-pixbuf
webp-pixbuf-loader@bullseye =
webp-pixbuf-loader@jammy =
gnome-epub-thumbnailer@bullseye =
gnome-epub-thumbnailer@jammy =
# Empty RHS = skip. These are soname-versioned in Debian (libpoppler-glib8,
# libgsf-1-114, libavif16, libjxl0.11 - the number changes every release) and
# tumbler/gdk-pixbuf pull the right one in as a dependency anyway, so naming a
# version here would break on the next release for no gain. libopenraw and its
# raw thumbnailer are in no Debian release at all; RAW previews are lost, which
# is a missing preview, not a broken desktop.
poppler-glib =
libgsf =
libavif =
libjxl =
libopenraw =
raw-thumbnailer =

# Apps whose Debian name differs (modules/telegram.sh, modules/viewers.sh).
webkit2gtk-4.1 = libwebkit2gtk-4.1-0
webkit2gtk-4.1@bullseye = libwebkit2gtk-4.0-37
# Debian dropped the mupdf backend (licence); poppler is the packaged one and
# zathura loads whichever backend is installed, so nothing else changes.
zathura-pdf-mupdf = zathura-pdf-poppler
# nsxiv reached Debian in bookworm. On bullseye/jammy `imv` (installed by the
# same module) is the image viewer; mapping to `sxiv` instead would install a
# binary and a .desktop id that mimeapps.list does not name.
nsxiv@bullseye =
nsxiv@jammy =

# Input methods (modules/fcitx5.sh). Debian splits fcitx5-gtk/fcitx5-qt into one
# binary package per toolkit version, and calls the config GUI fcitx5-config-qt.
fcitx5-gtk = fcitx5-frontend-gtk3 fcitx5-frontend-gtk4
fcitx5-qt = fcitx5-frontend-qt5 fcitx5-frontend-qt6
fcitx5-qt@jammy = fcitx5-frontend-qt5
fcitx5-configtool = fcitx5-config-qt

# Firefox: Debian ships the ESR under its own name and no `firefox` at all.
# Ubuntu's `firefox` IS a package - a snap stub - and modules/firefox.sh follows
# the snap's profile root rather than fighting it, so Ubuntu needs no row here.
firefox@bullseye = firefox-esr
firefox@bookworm = firefox-esr
firefox@trixie   = firefox-esr

# Rust tools that Debian does not package. The rice lists `rust` before the
# modules that need these (§4), so cargo: is a real route here, not a wish.
xcolor = cargo:xcolor
ouch = cargo:ouch
# betterlockscreen is a shell script published on GitHub, packaged by Void and by
# no Debian/Ubuntu release. It is not optional: the i3 config's xss-lock target
# and the $mod+Escape binding are both betterlockscreen, so without it the screen
# never locks - including on lid close.
betterlockscreen = source:provide_betterlockscreen
# autotiling is a ~100-line Python script on top of python3-i3ipc (which every
# release has); Debian packages it from trixie on.
autotiling = source:provide_autotiling
autotiling@trixie = autotiling

# Battery alerts: batsignal is in no Debian release. cbatticon is the packaged
# equivalent (tray icon + low/critical notifications) and is in all of them.
batsignal = cbatticon

# Empty RHS = skip: not in any Debian/Ubuntu release, and the rice still works
# without them. What is lost, in order: the rofi calc/emoji modes and the
# $mod+period emoji picker (fcitx5's own picker still works), two extra mixers
# on top of pavucontrol/pulsemixer, one of three MTP routes (gvfs-mtp and jmtpfs
# remain), touchpad swipe gestures, and kernel-level key remapping (xcape, which
# IS packaged, covers dual-role keys at the X level).
rofi-calc =
rofi-emoji =
rofimoji =
ncpamixer =
pwvucontrol =
simple-mtpfs =
libinput-gestures =
keyd =
keyd@trixie = keyd
# pamixer and qt6ct arrived in bookworm/noble. The volume keys go through
# ~/.config/i3/scripts/osd.sh, which falls back to pactl (pulseaudio-utils, in
# every release) when pamixer is absent, so the keys keep working on jammy.
pamixer@bullseye =
pamixer@jammy =
qt6ct@bullseye =
qt6ct@jammy =
# xautolock was removed in trixie; the idle timer there is xidlehook (cargo:),
# which modules/i3lock.sh prefers anyway when a Rust toolchain is present.
xautolock@trixie =

# xidlehook: the idle daemon that honours --not-when-audio / --not-when-fullscreen
# (i3-sugg §12 gotcha 14 - "screensaver kicks in during video"). Rust-only on
# every target; the xcb screensaver extension is a separate -dev package here,
# and libpulse-dev backs the audio inhibit.
xidlehook = cargo:xidlehook
xidlehook-build-deps = libxcb1-dev libxcb-screensaver0-dev libpulse-dev pkg-config

# exo-open is what Thunar's "Open Terminal Here" shells out to (modules/thunar.sh).
# Debian splits the library from the tools; only the tools half is wanted here.
exo = exo-utils

# zramen is Void-only (a runit service). Debian/Ubuntu init is systemd, which
# takes the zram-generator path in modules/swap.sh instead, so nothing is lost.
zramen =

# --- GPU drivers (modules/gpu-drivers.sh) -------------------------------
# Arch splits the GL/Vulkan stack per vendor (vulkan-radeon, vulkan-intel,
# vulkan-swrast, ...); Debian ships every Mesa Vulkan driver in one package, so
# all four vendor rows collapse onto mesa-vulkan-drivers. NVIDIA's proprietary
# branches are NOT mapped here - Debian/Ubuntu version their driver packages
# (nvidia-driver-<branch>) rather than carrying Arch's <branch>xx names, and the
# right branch per release has not been verified; an NVIDIA host still fails
# loudly on the first missing name, which is the documented behaviour (§1).
mesa = libgl1-mesa-dri libglx-mesa0
# Amber (pre-shader R100/R200 and Intel gen3-5) is packaged as DRI+GLX vendor
# libs here, with no standalone `mesa-amber`.
mesa-amber = libgl1-amber-dri libglx-amber0
vulkan-radeon = mesa-vulkan-drivers
vulkan-intel = mesa-vulkan-drivers
vulkan-swrast = mesa-vulkan-drivers
vulkan-virtio = mesa-vulkan-drivers
opencl-mesa = mesa-opencl-icd
# Intel's NEO compute runtime: same driver, Debian names it after the ICD.
intel-compute-runtime = intel-opencl-icd
ocl-icd = ocl-icd-libopencl1
libvdpau = libvdpau1
libvdpau-va-gl = libvdpau-va-gl1
libva-intel-driver = i965-va-driver
intel-media-driver = intel-media-va-driver
xf86-video-amdgpu = xserver-xorg-video-amdgpu
xf86-video-ati = xserver-xorg-video-ati
xf86-video-nouveau = xserver-xorg-video-nouveau
xf86-video-intel = xserver-xorg-video-intel
xf86-video-vmware = xserver-xorg-video-vmware

# 32-bit GL/Vulkan needs `dpkg --add-architecture i386`, which is off on a stock
# install - same call as any.map's `lib32-libnm =`. Empty RHS = skip, so the
# 64-bit stack still installs and the module does not fail on a name apt cannot
# see. Enable multilib by hand if you want 32-bit Steam/wine acceleration.
lib32-mesa =
lib32-mesa-amber =
lib32-vulkan-icd-loader =
lib32-vulkan-radeon =
lib32-vulkan-intel =
lib32-vulkan-virtio =
lib32-libvdpau =
lib32-libva-intel-driver =

# libgtop is the per-process accounting library Astra Monitor reads through GJS
# (modules/gnome-panel.c); what the extension imports is the typelib, which
# Debian ships in the GIR package rather than in the shared library one.
libgtop = gir1.2-gtop-2.0

# EasyEffects' plugin stack (modules/easyeffects.c) is named after the Arch
# runtime libraries; Debian carries the same shared objects under SONAME-suffixed
# binary package names.
libebur128 = libebur128-1
zita-convolver = libzita-convolver4
soundtouch = libsoundtouch1
libsamplerate = libsamplerate0
libsndfile = libsndfile1
libbs2b = libbs2b0
fftw = libfftw3-double3
speex = libspeex1
speexdsp = libspeexdsp1
calf = calf-plugins
# oneTBB's runtime moved from libtbb2 to libtbb12 in bookworm; bullseye and
# jammy still ship the old SONAME package only.
onetbb = libtbb12
onetbb@bullseye = libtbb2
onetbb@jammy = libtbb2
# Header-only library, so the -dev package is the whole thing.
nlohmann-json = nlohmann-json3-dev
# RNNoise is not in Debian at all: EasyEffects' noise reduction is optional and
# degrades to "filter unavailable", so skipping beats failing the install.
rnnoise =

jack2 = jackd2
pulseaudio-jack = pulseaudio-module-jack
xorg-xwayland = xwayland
# xlsclients lives in the x11-utils grab bag on Debian.
xorg-xlsclients = x11-utils
# `mako` on Debian is an unrelated ancient package; the Wayland daemon is
# mako-notifier.
mako = mako-notifier
libglvnd = libglvnd0
# policykit-1-gnome was dropped in trixie; mate-polkit is the same agent and is
# present on every release.
polkit-gnome@trixie = mate-polkit
# VS Code ships only from Microsoft's own apt repo, which the rice does not add.
vscode =

# --- old-release holes -------------------------------------------------------
# bullseye (11) and jammy (22.04) predate most of this desktop stack. Every row
# below is "absent from that release's archive", not a rename: empty RHS = skip,
# so the rest of the module still installs instead of aborting on one name.
alacritty@bullseye =
alacritty@jammy =
bibata-cursor-theme@bullseye =
