# gtklock and its userinfo module landed late and separately; the module is only
# in trixie and resolute so far.
gtklock@bullseye =
gtklock@bookworm =
gtklock@jammy =
gtklock-userinfo-module@bullseye =
gtklock-userinfo-module@bookworm =
gtklock-userinfo-module@jammy =
gtklock-userinfo-module@noble =

# Kvantum's Qt6 style is packaged separately and only exists in trixie/resolute;
# elsewhere the Qt5 style is the whole package.
kvantum = qt5-style-kvantum
kvantum@trixie = qt5-style-kvantum qt6-style-kvantum
kvantum@resolute = qt5-style-kvantum qt6-style-kvantum

# PipeWire's split metapackages arrived in bookworm. On bullseye and jammy the
# daemon is `pipewire` and the ALSA/JACK/Pulse shims all live in one package.
pipewire-audio@bullseye = pipewire
pipewire-audio@jammy = pipewire
pipewire-alsa@bullseye = pipewire-audio-client-libraries
pipewire-alsa@jammy = pipewire-audio-client-libraries
pipewire-jack@bullseye = pipewire-audio-client-libraries
pipewire-jack@jammy = pipewire-audio-client-libraries
pipewire-pulse@bullseye = pipewire-audio-client-libraries

# Ubuntu ships cpupower inside the kernel tools, not as its own package.
cpupower@jammy = linux-tools-common linux-tools-generic
cpupower@noble = linux-tools-common linux-tools-generic
cpupower@resolute = linux-tools-common linux-tools-generic
# elogind exists only where systemd does not; Ubuntu dropped the package.
elogind@jammy =
elogind@noble =
elogind@resolute =

# dnscrypt-proxy was pulled from bookworm (RC bug at the freeze) and is back in
# trixie; openresolv left Ubuntu after noble, where systemd-resolved owns
# /etc/resolv.conf anyway. Empty RHS = skip: dnscrypt.c still installs the rest.
dnscrypt-proxy@bookworm =
openresolv@noble =
openresolv@resolute =
# jmtpfs and p7zip are both gone from resolute; 7zip is the maintained fork.
jmtpfs@resolute =
p7zip@resolute = 7zip

# ninja is ninja-build here (the `ninja` package is something else).
cuik-build-deps = luajit ninja-build nasm clang lld
